const inputClass = 'h-9 w-full rounded-control border border-line bg-canvas px-3 text-[13px] text-ink outline-none placeholder:text-ink-3 transition focus:border-accent focus:bg-surface focus:ring-2 focus:ring-accent-tint disabled:cursor-not-allowed disabled:opacity-55';
const panelClass = 'rounded-card border border-line bg-surface shadow-hairline';
const defaultLevels = ['off', 'low', 'medium', 'high'] as const;
const allLevels = ['off', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max'] as const;
const contextPresets = ['64K', '128K', '200K', '256K', '1M'];
const outputPresets = ['4K', '8K', '16K', '32K', '64K'];
const providerGradients = [
 'from-zinc-700 to-zinc-950',
 'from-blue-600 to-indigo-700',
 'from-cyan-600 to-blue-700',
 'from-emerald-600 to-teal-700',
 'from-violet-600 to-fuchsia-700',
 'from-amber-600 to-orange-700',
 'from-rose-600 to-pink-700'
] as const;
const inputOptions: Array<{ value: ModelInputModality; label: string; description: string; icon: typeof MessageSquare; color: 'blue' | 'purple' }> = [
 { value: 'text', label: '文本', description: '支持标准对话与多轮文本上下文', icon: MessageSquare, color: 'blue' },
 { value: 'image', label: '图片', description: '支持多模态视觉图像输入 (Vision)', icon: ImageIcon, color: 'purple' }
];

function probeFailureMessage(status: ProviderProbeResult['upstreamStatus']) {
 const messages: Record<ProviderProbeResult['upstreamStatus'], string> = {
 MODEL_DIRECTORY_UNSUPPORTED: '上游连接可用，但没有兼容的模型目录接口',
 AUTHENTICATION_FAILED: 'API Key 未通过上游认证',
 UPSTREAM_REJECTED: '上游拒绝了模型目录请求',
 INVALID_RESPONSE: '上游返回的模型目录格式无法识别',
 UNAVAILABLE: '上游暂时不可用',
 TIMEOUT: '上游响应超时',
 SUCCESS: '模型目录读取失败'
 };
 return messages[status];
}

export function discoveredCapacity(value?: number | null) {
 return value == null ? undefined : formatTokenCapacity(value);
}

type ReasoningTier = { id: string; name: string; value: string | null };
type ModelDraft = {
 id: string;
 name: string;
 contextWindow: string;
 maxTokens: string;
 input: ModelInputModality[];
 reasoningEnabled: boolean;
 reasoning: ReasoningTier[];
 expanded: boolean;
 manual: boolean;
 existingModel?: ManagedModel;
};

function TextField({ label, value, onChange, type = 'text', placeholder, readOnly = false, icon: Icon, suffix }: { label: React.ReactNode; value: string; onChange?: (value: string) => void; type?: string; placeholder?: string; readOnly?: boolean; icon?: typeof Cpu; suffix?: React.ReactNode }) {
 return <label className="grid gap-1.5 text-[12.5px] font-medium text-ink-2"><span>{label}</span><span className="relative block">{Icon ? <Icon aria-hidden className="pointer-events-none absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-ink-3" /> : null}<input className={`${inputClass} ${Icon ? 'pl-9' : ''} ${suffix ? 'pr-20' : ''} ${readOnly ? 'cursor-not-allowed bg-inset text-ink-3' : ''}`} readOnly={readOnly} type={type} value={value} placeholder={placeholder} onChange={(event) => onChange?.(event.target.value)} />{suffix ? <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 font-mono text-[10px] text-ink-3">{suffix}</span> : null}</span></label>;
}

function Footer({ onClose, saving, label = '保存', disabled = false, className, sticky = false }: { onClose: () => void; saving: boolean; label?: string; disabled?: boolean; className?: string; sticky?: boolean }) {
 return <DialogFooter className={className} sticky={sticky}><Button type="button" size="sm" onClick={onClose}>取消</Button><Button type="submit" variant="primary" size="sm" disabled={saving || disabled}>{saving ? '保存中' : label}<ChevronRight className="size-3.5" /></Button></DialogFooter>;
}

export function providerGradient(providerId?: string, fallbackName = '') {
 const key = providerId || fallbackName || 'provider';
 let hash = 0;
 for (let index = 0; index < key.length; index += 1) hash = (hash * 31 + key.charCodeAt(index)) >>> 0;
 return providerGradients[hash % providerGradients.length];
}

export function ProviderEditorDialog({ current, error, onClose, onSave, saving }: { current?: Provider; error?: string; onClose: () => void; onSave: (value: ModelProviderCreateRequest | ModelProviderUpdateRequest) => void; saving: boolean }) {
 const [name, setName] = React.useState(current?.name ?? '');
 const [description, setDescription] = React.useState(current?.description ?? '');
 return <ProductDialog className="max-w-[600px] overflow-y-auto rounded-2xl border-line/90 " title={current ? '编辑供应商信息' : '新建供应商'} onClose={onClose}><form className="grid gap-5 bg-canvas/50 p-5" onSubmit={(event) => { event.preventDefault(); if (name.trim()) onSave({ name: name.trim(), description: description.trim() }); }}><div className={`${panelClass} flex items-start gap-3 p-4`}><div className="grid size-9 shrink-0 place-items-center rounded-xl bg-gradient-to-br from-blue-600 to-indigo-600 text-white"><Server className="size-4" /></div><div><p className="m-0 text-sm font-semibold text-ink ">供应商元信息</p><p className="mt-1 mb-0 text-[11px] leading-5 text-ink-3 ">端点与 API Key 属于连接，协议也随连接配置，本页只维护供应商身份。</p></div></div><div className="grid gap-4"><TextField label="供应商名称" value={name} onChange={setName} placeholder="例如：OpenAI Compatible" /><TextField label="供应商描述（选填）" value={description} onChange={setDescription} placeholder="例如：团队统一的 OpenAI 兼容网关" /></div>{error ? <p role="alert" className="m-0 flex items-center gap-2 rounded-xl bg-red-tint px-3 py-2 text-xs text-red "><AlertCircle className="size-3.5" />{error}</p> : null}<Footer sticky onClose={onClose} saving={saving} disabled={!name.trim()} label="保存" /></form></ProductDialog>;
}

export function connectionDraftDefaults(current?: ModelProviderConnection, copyFrom?: ModelProviderConnection) {
 const source = copyFrom ?? current;
 return {
 name: copyFrom ? copyFrom.name + ' 副本' : current?.name ?? '',
 apiProtocol: source?.apiProtocol ?? 'openai-completions',
 baseUrl: source?.baseUrl ?? '',
 modelDiscoveryPath: source?.modelDiscoveryPath ?? '/models',
 connectTimeoutMs: source?.connectTimeoutMs ?? 5000,
 readTimeoutMs: source?.readTimeoutMs ?? 120000
 };
}

export function ConnectionEditorDialog({ provider, current, copyFrom, error, onClose, onProbe, onSave, saving }: { provider: Provider; current?: ModelProviderConnection; copyFrom?: ModelProviderConnection; error?: string; onClose: () => void; onProbe: (value: ProviderProbeRequestWritable) => Promise<ProviderProbeResult>; onSave: (value: ModelProviderConnectionCreateRequestWritable | ModelProviderConnectionUpdateRequestWritable) => void; saving: boolean }) {
 const defaults = connectionDraftDefaults(current, copyFrom);
 const [name, setName] = React.useState(defaults.name);
 const [apiProtocol, setApiProtocol] = React.useState(defaults.apiProtocol);
 const [baseUrl, setBaseUrl] = React.useState(defaults.baseUrl);
 const [modelDiscoveryPath, setModelDiscoveryPath] = React.useState(defaults.modelDiscoveryPath);
 const [credential, setCredential] = React.useState('');
 const [replaceSecret, setReplaceSecret] = React.useState(false);
 const [showKey, setShowKey] = React.useState(false);
 const [probe, setProbe] = React.useState<ProviderProbeResult>();
 const [probing, setProbing] = React.useState(false);
 const probeDraft = async () => { setProbing(true); try { setProbe(await onProbe({ apiProtocol, baseUrl, modelDiscoveryPath, credential, connectTimeoutMs: defaults.connectTimeoutMs, readTimeoutMs: defaults.readTimeoutMs })); } finally { setProbing(false); } };
 const valid = Boolean(name.trim() && baseUrl.trim() && (!current ? credential.trim() : !replaceSecret || credential.trim()));
 const endpoint = baseUrl.trim().replace(/\/+$/, '') || 'https://api.example.com/v1';
 return <ProductDialog className="max-w-[760px] overflow-y-auto rounded-2xl border-line/90 " title={current ? `编辑连接 · ${provider.name}` : `新建连接 · ${provider.name}`} onClose={onClose}><form className="grid gap-5 bg-canvas/50 p-5" onSubmit={(event) => { event.preventDefault(); if (!valid) return; onSave(current ? { name: name.trim(), baseUrl: baseUrl.trim(), modelDiscoveryPath, replaceSecret, ...(replaceSecret ? { credential } : {}), connectTimeoutMs: current.connectTimeoutMs, readTimeoutMs: current.readTimeoutMs } : { name: name.trim(), apiProtocol, baseUrl: baseUrl.trim(), modelDiscoveryPath, credential, connectTimeoutMs: defaults.connectTimeoutMs, readTimeoutMs: defaults.readTimeoutMs }); }}><div className={`${panelClass} flex items-center gap-3 p-4`}><div className={`grid size-10 shrink-0 place-items-center rounded-xl bg-gradient-to-br ${providerGradient(provider.id, provider.name)} text-sm font-bold text-white`}>{provider.name.slice(0, 1).toUpperCase()}</div><div className="min-w-0"><p className="m-0 truncate text-sm font-semibold text-ink ">{provider.name}</p><p className="mt-1 mb-0 text-[11px] text-ink-3 ">为此供应商配置一个新的 API 连接</p></div></div><section className={`${panelClass} grid gap-5 overflow-hidden`}><div className="grid gap-4 p-5 sm:grid-cols-2"><TextField label="连接名称" value={name} onChange={setName} placeholder="例如：生产连接" /><label className="grid gap-1.5 text-[11px] font-semibold text-ink-2 ">API 协议<select className={`${inputClass} pl-3`} value={apiProtocol} onChange={(event) => setApiProtocol(event.target.value as typeof apiProtocol)} disabled={Boolean(current)}><option value="openai-completions">OpenAI Chat Completions</option><option value="openai-responses">OpenAI Responses</option><option value="anthropic-messages">Anthropic Messages</option></select></label></div><div className="grid gap-4 border-t border-line px-5 py-5"><TextField label="Base URL" value={baseUrl} onChange={setBaseUrl} placeholder="https://api.example.com/v1" icon={Globe} /><TextField label="模型发现接口" value={modelDiscoveryPath} onChange={setModelDiscoveryPath} placeholder="/models" /><div className="flex items-center justify-between rounded-xl border border-line/70 bg-canvas px-3 py-2 font-mono text-[11px]"><span className="rounded bg-line/80 px-1.5 py-0.5 text-[10px] font-bold text-ink-2 ">GET</span><span className="min-w-0 truncate text-ink-3 ">{endpoint}<strong className="text-ink-2 ">{modelDiscoveryPath}</strong></span><span className="shrink-0 text-[10px] text-ink-3 ">模型目录预览</span></div><div className="grid gap-1.5"><div className="flex items-center justify-between"><label className="text-[11px] font-semibold text-ink-2 ">API Key</label><span className="inline-flex items-center gap-1 text-[10px] font-medium text-green "><Lock className="size-3" />保存后仅显示状态</span></div>{current && !replaceSecret ? <div className="flex h-10 items-center justify-between rounded-xl border border-line/90 bg-field/80 px-3 text-xs text-ink-3 "><span>连接密钥</span><strong className="font-medium text-green ">{current.credentialConfigured ? '已配置 · 原文不会回填' : '未配置'}</strong><button type="button" className="text-accent hover:text-accent-ink " onClick={() => setReplaceSecret(true)}>替换</button></div> : <div className="relative"><KeyRound className="pointer-events-none absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-ink-3 " /><input aria-label="API Key" className={`${inputClass} pl-9 pr-20 font-mono`} type={showKey ? 'text' : 'password'} value={credential} onChange={(event) => setCredential(event.target.value)} placeholder="输入连接密钥 (例如 sk-...)" /><button type="button" className="absolute right-2 top-1/2 inline-flex -translate-y-1/2 items-center gap-1 rounded-full px-2 py-1 text-[10px] text-ink-3 hover:bg-field hover:text-ink " onClick={() => setShowKey((value) => !value)}>{showKey ? <EyeOff className="size-3.5" /> : <Eye className="size-3.5" />}{showKey ? '隐藏' : '显示'}</button></div>}</div></div><div className="flex flex-col gap-3 border-t border-line bg-canvas/90 px-5 py-3.5 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-2 text-[11px] text-ink-3 ">{probe?.success ? <><CheckCircle2 className="size-4 text-green " /><span className="font-medium text-green ">端点握手成功 · 可获取 {probe.models.length} 个模型</span></> : probe ? <><AlertCircle className="size-4 text-red " /><span className="font-medium text-red ">连接测试失败 · {probe.upstreamStatus}</span></> : <><ShieldCheck className="size-4 text-accent " /><span>下一步获取可用模型会验证端点和 API Key</span></>}</div><Button type="button" size="xs" className="self-end border border-line bg-surface text-ink-2 shadow-[0_1px_2px_rgba(0,0,0,.04)] hover:bg-field sm:self-auto" disabled={probing || !baseUrl.trim() || (!current && !credential.trim())} onClick={() => void probeDraft()}><RefreshCw className={`size-3.5 ${probing ? 'animate-spin text-accent ' : 'text-ink-3 '}`} />{probing ? '正在验证…' : '测试连通性（可选）'}</Button></div></section>{error ? <p role="alert" className="m-0 flex items-center gap-2 rounded-xl bg-red-tint px-3 py-2 text-xs text-red "><AlertCircle className="size-3.5" />{error}</p> : null}<Footer sticky onClose={onClose} saving={saving} disabled={!valid} label="保存连接" /></form></ProductDialog>;
}

function reasoningTiers(model?: ManagedModel, _discovered?: ProviderDiscoveredModel): ReasoningTier[] {
 const value = model?.reasoningEfforts;
 if (value && typeof value === 'object') return Object.entries(value).map(([id, wire]) => ({ id, name: id, value: wire ?? null }));
 return defaultLevels.map((id) => ({ id, name: id, value: id === 'off' ? null : id }));
}

function draftFrom(model?: ManagedModel, discovered?: ProviderDiscoveredModel, manual = false): ModelDraft {
 const reasoning = reasoningTiers(model, discovered);
 return { id: model?.modelId ?? discovered?.id ?? '', name: model?.name ?? discovered?.name ?? '', contextWindow: formatTokenCapacity(model?.contextWindow ?? discovered?.contextWindow ?? 256000), maxTokens: formatTokenCapacity(model?.maxTokens ?? discovered?.maxTokens ?? 32768), input: model?.input?.length ? [...model.input] : ['text'], reasoningEnabled: model?.reasoningEfforts !== false && Boolean(model?.reasoningEfforts), reasoning, expanded: Boolean(model) || manual, manual, existingModel: model };
}

function tierStrength(id: string, index: number) { return id === 'off' ? 0 : Math.min(Math.max(allLevels.indexOf(id as typeof allLevels[number]), index + 1), 4); }

function defaultTierValue(level: string) { return level === 'off' ? null : level; }

export function nextReasoningLevel(current: ReadonlyArray<ReasoningTier>) {
 const used = current.map((tier) => tier.id);
 const highest = Math.max(-1, ...used.map((level) => allLevels.indexOf(level as typeof allLevels[number])));
 return allLevels.find((level, index) => index > highest && !used.includes(level)) ?? allLevels.find((level) => !used.includes(level));
}

function reasoningError(reasoning: ReadonlyArray<ReasoningTier>) {
 if (reasoning.some((tier) => tier.id !== 'off' && !tier.value?.trim())) return '推理档位的 API 参数值不能为空。';
 return reasoning.some((tier) => tier.id !== 'off') ? undefined : '至少保留一个非 off 推理档位。';
}

function ModelConfigCard({ draft, index, onChange, onRemove }: { draft: ModelDraft; index: number; onChange: (value: ModelDraft) => void; onRemove?: () => void }) {
 const update = (patch: Partial<ModelDraft>) => onChange({ ...draft, ...patch });
 const hasId = Boolean(draft.id.trim());
 const parsedMaxTokens = (() => { try { return parseTokenCapacity(draft.maxTokens); } catch { return undefined; } })();
 const setInput = (value: ModelInputModality) => { if (draft.input.length === 1 && draft.input[0] === value) return; update({ input: draft.input.includes(value) ? draft.input.filter((item) => item !== value) : [...draft.input, value] }); };
 const removeTier = (id: string) => update({ reasoning: draft.reasoning.filter((tier) => tier.id !== id) });
 const changeTier = (tier: ReasoningTier, nextId: string) => { const carried = tier.value && tier.value !== tier.id && tier.id !== 'off' && nextId !== 'off' ? tier.value : defaultTierValue(nextId); update({ reasoning: draft.reasoning.map((item) => item.id === tier.id ? { id: nextId, name: nextId, value: carried } : item) }); };
 const editTierValue = (tier: ReasoningTier, value: string) => update({ reasoning: draft.reasoning.map((item) => item.id === tier.id ? { ...item, value: value.trim() } : item) });
 const repairTierValue = (tier: ReasoningTier) => { if (tier.id !== 'off' && !tier.value?.trim()) editTierValue(tier, tier.id); };
 const addTier = () => { const next = nextReasoningLevel(draft.reasoning); if (next) update({ reasoning: [...draft.reasoning, { id: next, name: next, value: defaultTierValue(next) }] }); };
 const reasoningIssue = draft.reasoningEnabled ? reasoningError(draft.reasoning) : undefined;
 return <article className={`group/card overflow-hidden rounded-2xl border bg-surface transition ${draft.expanded ? 'border-line-strong/90 shadow-md ring-1 ring-ink/5 ' : 'border-line/90 shadow-[0_1px_2px_rgba(0,0,0,.03)] hover:border-line-strong '}`}><div className={`flex cursor-pointer items-center justify-between gap-3 px-5 py-3.5 ${draft.expanded ? 'border-b border-line/70 bg-canvas/90 ' : 'hover:bg-canvas/50 '}`} onClick={() => update({ expanded: !draft.expanded })}><div className="flex min-w-0 items-center gap-3"><div className={`grid size-7 shrink-0 place-items-center rounded-lg border text-xs font-bold ${hasId ? 'border-green bg-green-tint text-green ' : 'border-orange bg-orange-tint text-orange '}`}>{hasId ? <Check className="size-3.5" /> : index + 1}</div><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="truncate text-xs font-semibold text-ink sm:text-sm">{hasId ? (draft.name || draft.id) : '手动模型 · 待填写上游 ID'}</span>{hasId ? <span className="truncate rounded-md border border-line/80 bg-surface px-2 py-0.5 font-mono text-[11px] text-ink-2 ">{draft.id}</span> : <span className="inline-flex items-center gap-1 rounded-full border border-orange/70 bg-orange-tint/90 px-2 py-0.5 text-[10px] font-medium text-orange "><span className="size-1.5 animate-pulse rounded-full bg-orange " />必填项待完善</span>}</div>{draft.expanded ? <p className="mt-0.5 mb-0 text-[11px] text-ink-3 ">显示名称由后台按上游模型 ID 生成，也可以在保存前自定义。</p> : <div className="mt-1.5 flex flex-wrap items-center gap-1.5"><span className="rounded bg-field px-1.5 py-0.5 font-mono text-[10px] text-ink-2 ">窗口 {draft.contextWindow}</span><span className="rounded bg-field px-1.5 py-0.5 font-mono text-[10px] text-ink-2 ">输出 {draft.maxTokens}</span>{draft.input.includes('text') ? <span className="rounded bg-accent-tint px-1.5 py-0.5 text-[10px] font-medium text-accent ">文本</span> : null}{draft.input.includes('image') ? <span className="rounded bg-accent-tint px-1.5 py-0.5 text-[10px] font-medium text-accent-ink ">图片</span> : null}{draft.reasoningEnabled ? <span className="rounded border border-orange/60 bg-orange-tint px-1.5 py-0.5 text-[10px] font-medium text-orange ">推理（{draft.reasoning.length} 档）</span> : null}</div>}</div></div><div className="flex shrink-0 items-center gap-1" onClick={(event) => event.stopPropagation()}><button type="button" title="克隆此模型配置" className="hidden rounded-full p-1.5 text-ink-3 transition hover:bg-line/60 hover:text-ink-2 sm:inline-flex"><Copy className="size-3.5" /></button><button type="button" className="inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-medium text-ink-2 transition hover:bg-line/60 hover:text-ink " onClick={() => update({ expanded: !draft.expanded })}>{draft.expanded ? '收起配置' : '展开配置'}<ChevronDown className={`size-3.5 text-ink-3 transition-transform ${draft.expanded ? 'rotate-180' : ''}`} /></button>{onRemove ? <button type="button" className="rounded-full px-2.5 py-1 text-xs font-medium text-red transition hover:bg-red-tint " onClick={onRemove}>移除</button> : null}</div></div>{draft.expanded ? <div className="grid gap-5 bg-surface p-5 text-xs"><div className="grid gap-4 sm:grid-cols-2"><TextField label="上游模型 ID" value={draft.id} readOnly={!draft.manual} onChange={(id) => update({ id, name: draft.name || id })} placeholder="例如：gpt-4.1" icon={Cpu} /><TextField label={<>显示名称 <span className="font-normal text-ink-3 ">（可选）</span><span className="ml-1 inline-flex items-center gap-0.5 text-[10px] font-normal text-ink-3 "><Sparkles className="size-2.5 text-accent " />自动跟随</span></>} value={draft.name} onChange={(name) => update({ name })} placeholder={draft.id ? `${draft.id}（后台默认生成）` : '由后台按上游模型 ID 生成'} /></div><div className="grid gap-4 sm:grid-cols-2"><div className="grid gap-1.5"><div className="flex items-center justify-between"><span className="text-[11px] font-semibold text-ink-2 ">上下文窗口</span><div className="flex items-center gap-0.5 rounded-lg border border-line/60 bg-field p-0.5">{contextPresets.map((preset) => <button key={preset} type="button" className={`rounded-full px-1.5 py-0.5 font-mono text-[10px] transition ${draft.contextWindow === preset ? 'bg-surface font-semibold text-ink shadow-sm' : 'text-ink-3 hover:text-ink '}`} onClick={() => update({ contextWindow: preset })}>{preset}</button>)}</div></div><TextField label="" value={draft.contextWindow} onChange={(contextWindow) => update({ contextWindow })} placeholder="256K" suffix="Tokens" /></div><div className="grid gap-1.5"><div className="flex items-center justify-between"><span className="text-[11px] font-semibold text-ink-2 ">最大输出 Token</span><div className="flex items-center gap-0.5 rounded-lg border border-line/60 bg-field p-0.5">{outputPresets.map((preset) => <button key={preset} type="button" className={`rounded-full px-1.5 py-0.5 font-mono text-[10px] transition ${parsedMaxTokens === parseTokenCapacity(preset) ? 'bg-surface font-semibold text-ink shadow-sm' : 'text-ink-3 hover:text-ink '}`} onClick={() => update({ maxTokens: preset })}>{preset}</button>)}</div></div><TextField label="" value={draft.maxTokens} onChange={(maxTokens) => update({ maxTokens })} placeholder="32K" suffix="Max Out" /></div></div><section className="grid gap-3 rounded-2xl border border-line/80 bg-canvas/70 p-4"><div className="flex items-center justify-between"><span className="font-semibold text-ink ">输入类型</span><span className="text-[11px] text-ink-3 ">至少保留一种输入类型，默认是文本。</span></div><div className="grid gap-3 sm:grid-cols-2">{inputOptions.map(({ value, label, description, icon: Icon, color }) => { const active = draft.input.includes(value); return <button type="button" key={value} onClick={() => setInput(value)} className={`flex items-center justify-between rounded-xl border p-3 text-left transition ${active ? 'border-accent/80 bg-surface ring-2 ring-accent/10 shadow-sm' : 'border-line/80 bg-surface/60 text-ink-3 hover:bg-surface '}`}><span className="flex items-center gap-3"><span className={`grid size-8 place-items-center rounded-lg ${active ? color === 'blue' ? 'bg-accent-tint text-accent ' : 'bg-accent-tint text-accent-ink ' : 'bg-field text-ink-3 '}`}><Icon className="size-4" /></span><span><strong className="block text-xs text-ink ">{label}</strong><small className="mt-1 block text-[10px] text-ink-3 ">{description}</small></span></span><span className={`grid size-4 place-items-center rounded border ${active ? 'border-accent bg-accent text-white' : 'border-line-strong bg-surface '}`}>{active ? <Check className="size-3" /> : null}</span></button>; })}</div></section><section className={`grid gap-4 rounded-2xl border p-4 transition ${draft.reasoningEnabled ? 'border-orange/90 bg-gradient-to-b from-amber-50/40 via-white dark:via-surface to-white dark:to-surface shadow-sm' : 'border-line/80 bg-canvas/70 '}`}><div className="flex items-start justify-between gap-4"><div className="flex items-start gap-3"><div className={`grid size-9 shrink-0 place-items-center rounded-xl border ${draft.reasoningEnabled ? 'border-orange bg-orange text-white shadow-sm' : 'border-line bg-surface text-ink-3 '}`}><BrainCircuit className="size-4" /></div><div><div className="flex items-center gap-2"><span className="font-semibold text-ink ">推理能力</span><span className={`rounded-full border px-2 py-0.5 text-[10px] font-medium ${draft.reasoningEnabled ? 'border-orange/80 bg-orange-tint text-orange ' : 'border-line/60 bg-field text-ink-3 '}`}>{draft.reasoningEnabled ? '已启用推理档位' : '未启用'}</span></div><p className="mt-1 mb-0 text-[11px] leading-relaxed text-ink-3 ">off 表示关闭思考，不填写参数值；其他档位默认与档位名相同，可按上游 API 文档修改。</p></div></div><button type="button" role="switch" aria-checked={draft.reasoningEnabled} onClick={() => update({ reasoningEnabled: !draft.reasoningEnabled })} className={`relative inline-flex h-6 w-11 shrink-0 rounded-full border-2 border-transparent transition ${draft.reasoningEnabled ? 'bg-ink ' : 'bg-line-strong '}`}><span className={`pointer-events-none inline-block size-5 rounded-full bg-surface shadow-md transition ${draft.reasoningEnabled ? 'translate-x-5' : 'translate-x-0'}`} /></button></div>{draft.reasoningEnabled ? <div className="grid gap-3 border-t border-line/70 pt-3.5"><div className="flex justify-end"><button type="button" className="inline-flex items-center gap-1 rounded-full border border-accent bg-surface px-3 py-1 text-[11px] font-semibold text-accent shadow-sm transition hover:bg-accent hover:text-white disabled:cursor-not-allowed disabled:opacity-50" disabled={allLevels.every((level) => draft.reasoning.some((tier) => tier.id === level))} onClick={addTier}><Plus className="size-3" />添加档位</button></div><div className="overflow-hidden rounded-xl border border-line/90 bg-surface shadow-sm"><div className="grid grid-cols-12 gap-3 bg-canvas/90 px-4 py-2 text-[11px] font-semibold text-ink-3 "><div className="col-span-5">档位名称（Tier）</div><div className="col-span-5">上游参数值（API Value）</div><div className="col-span-2 text-right">操作</div></div>{draft.reasoning.map((tier, tierIndex) => { const strength = tierStrength(tier.id, tierIndex); return <div key={tier.id} className="grid grid-cols-12 items-center gap-3 px-4 py-2.5 transition hover:bg-canvas/60 "><div className="col-span-4 flex min-w-0 items-center gap-2.5"><div className="flex h-3.5 w-4 shrink-0 items-end gap-0.5">{[1, 2, 3, 4].map((bar) => <span key={bar} className={`w-0.5 rounded-full ${bar === 1 ? 'h-1.5' : bar === 2 ? 'h-2' : bar === 3 ? 'h-2.5' : 'h-3.5'} ${bar <= strength ? 'bg-orange ' : 'bg-line '}`} />)}</div><select aria-label={`档位名称 ${tierIndex + 1}`} className={`${inputClass} h-8 py-1`} value={tier.id} onChange={(event) => changeTier(tier, event.target.value)}>{!allLevels.includes(tier.id as typeof allLevels[number]) ? <option value={tier.id}>{tier.name}</option> : null}{allLevels.filter((level) => level === tier.id || !draft.reasoning.some((item) => item.id === level)).map((level) => <option key={level} value={level}>{level}</option>)}</select></div><div className="col-span-6"><div className="relative"><input aria-label={`${tier.id} API 参数值`} className={`${inputClass} h-8 rounded-lg bg-canvas/70 py-1.5 pr-16 font-mono disabled:cursor-not-allowed disabled:opacity-60`} value={tier.value ?? ''} disabled={tier.id === 'off'} onChange={(event) => editTierValue(tier, event.target.value)} onBlur={() => repairTierValue(tier)} placeholder={tier.id === 'off' ? '关闭思考' : tier.id} />{tier.id !== 'off' && tier.value !== tier.id ? <button type="button" className="absolute right-2 top-1/2 -translate-y-1/2 rounded-full bg-accent-tint px-1.5 py-0.5 text-[10px] text-accent " onClick={() => editTierValue(tier, tier.id)}>同档位名</button> : null}</div></div><div className="col-span-2 flex items-center justify-end gap-1.5"><button type="button" className="rounded-full p-1 text-ink-3 transition hover:bg-red-tint hover:text-red " title="删除推理档位" onClick={() => removeTier(tier.id)}><Trash2 className="size-3.5" /></button></div></div>; })}</div>{reasoningIssue ? <p role="alert" className="m-0 text-[11px] leading-5 text-red ">{reasoningIssue}</p> : null}<p className="m-0 text-[11px] leading-5 text-ink-3 ">档位名称是 DSH canonical key，API 参数值按每行映射发送；off 表示关闭思考。</p></div> : null}</section></div> : null}</article>;
}

export type ModelSaveEntry = { existingModel?: ManagedModel; value: ManagedModelWriteRequest };
type ModelEditorProps = { current?: ManagedModel; existingModels?: ReadonlyArray<ManagedModel>; connection?: ModelProviderConnection; connections: ReadonlyArray<ModelProviderConnection>; error?: string; onClose: () => void; onDiscover: (connectionId: string) => Promise<ProviderProbeResult>; onSave: (value: ModelSaveEntry[]) => void; saving: boolean };
function modelPayload(connectionId: string, draft: ModelDraft, sortOrder: number): ManagedModelWriteRequest {
 const reasoning = draft.reasoning.reduce<Record<string, string | null>>((result, tier) => { result[tier.id] = tier.value ?? defaultTierValue(tier.id); return result; }, {});
 return { connectionId, modelId: draft.id.trim(), ...(draft.name.trim() ? { name: draft.name.trim() } : {}), contextWindow: parseTokenCapacity(draft.contextWindow) ?? 256000, maxTokens: parseTokenCapacity(draft.maxTokens) ?? 32768, input: draft.input.length ? draft.input : ['text'], reasoningEfforts: draft.reasoningEnabled ? reasoning as ManagedModelWriteRequest['reasoningEfforts'] : false, sortOrder };
}

export function ModelEditorDialog({ current, existingModels = [], connection, connections, error, onClose, onDiscover, onSave, saving }: ModelEditorProps) {
 const initialConnection = current?.connectionId ?? connection?.id ?? connections[0]?.id ?? '';
 const [connectionId, setConnectionId] = React.useState(initialConnection);
 const [discovered, setDiscovered] = React.useState<ProviderDiscoveredModel[]>([]);
 const [drafts, setDrafts] = React.useState<ModelDraft[]>(current ? [draftFrom(current)] : existingModels.map((model) => draftFrom(model)));
 const [discovering, setDiscovering] = React.useState(false);
 const [discoverError, setDiscoverError] = React.useState<string>();
 React.useEffect(() => {
 if (!current && existingModels.length && drafts.length === 0) setDrafts(existingModels.map((model) => draftFrom(model)));
 }, [current, existingModels, drafts.length]);
 const runDiscover = async () => { if (!connectionId) return; setDiscovering(true); setDiscoverError(undefined); try { const result = await onDiscover(connectionId); setDiscovered(result.models); if (!result.success) setDiscoverError(`${probeFailureMessage(result.upstreamStatus)}，仍可手动新增模型。`); } catch (cause) { setDiscoverError(cause instanceof Error ? cause.message : '模型发现失败'); } finally { setDiscovering(false); } };
 const add = (model: ProviderDiscoveredModel) => setDrafts((items) => { const selected = items.find((draft) => draft.id === model.id); if (selected?.existingModel) return items; return selected ? items.filter((draft) => draft.id !== model.id) : [...items, draftFrom(undefined, model)]; });
 const invalidReasoning = drafts.some((draft) => draft.reasoningEnabled && reasoningError(draft.reasoning));
 const submit = () => { if (!connectionId || drafts.some((draft) => !draft.id.trim()) || invalidReasoning) return; onSave(drafts.map((draft) => ({ existingModel: draft.existingModel, value: modelPayload(connectionId, draft, draft.existingModel?.sortOrder ?? current?.sortOrder ?? 100) }))); };
 return <ProductDialog className="flex min-h-0 max-w-[960px] flex-col overflow-hidden rounded-2xl border-line/90 " title="维护模型" onClose={onClose}><form className="grid min-h-0 flex-1 grid-rows-[minmax(0,1fr)_auto] bg-canvas/50 " onSubmit={(event) => { event.preventDefault(); submit(); }}><div className="min-h-0 space-y-5 overflow-y-auto overscroll-contain p-5"><section className={`${panelClass} relative overflow-hidden p-5`}><div className="absolute -right-14 -top-14 size-36 rounded-full bg-gradient-to-bl from-blue-500/10 via-indigo-500/5 to-transparent" /><div className="relative flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div className="flex items-start gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-xl border border-line/80 bg-canvas text-ink-2 "><Server className="size-4" /></div><div><div className="flex flex-wrap items-center gap-2"><h3 className="m-0 text-sm font-semibold text-ink ">{current ? '当前模型' : '可用模型'}</h3>{connection ? <span className="inline-flex items-center gap-1 rounded-full border border-line/60 bg-field/90 px-2 py-0.5 text-[10px] font-medium text-ink-3 "><span className="size-1.5 rounded-full bg-green " />{connection.name}</span> : null}{discovered.length ? <span className="rounded-full border border-green/60 bg-green-tint px-2 py-0.5 text-[10px] font-semibold text-green ">已同步 {discovered.length} 款候选</span> : null}</div><p className="mt-1 mb-0 text-[11px] leading-relaxed text-ink-3 ">{current ? '当前模型已定位到下方配置卡片，修改后保存。' : existingModels.length ? '当前连接已有模型已载入下方维护列表，可直接修改；发现的新模型会以新增草稿加入。' : '获取当前连接的模型目录，选择候选模型后进入下方维护列表；发现失败时仍可手动新增。'}</p></div></div>{!current ? <Button type="button" size="sm" className="self-start border border-line/90 bg-surface text-ink shadow-sm hover:bg-ink hover:text-canvas" disabled={discovering || !connectionId} onClick={() => void runDiscover()}><RefreshCw className={`size-3.5 ${discovering ? 'animate-spin' : ''}`} />{discovering ? '正在探测…' : discovered.length ? '重新获取' : '获取可用模型'}</Button> : null}</div>{!current && !connection ? <label className="relative mt-4 grid gap-1.5 text-[11px] font-semibold text-ink-2 ">连接<select className={`${inputClass} pl-3`} value={connectionId} onChange={(event) => { setConnectionId(event.target.value); setDiscovered([]); setDrafts([]); }}>{connections.map((item) => <option key={item.id} value={item.id}>{item.providerName} · {item.name}</option>)}</select></label> : null}{!current && discovered.length ? <div className="mt-4 grid gap-2 border-t border-line pt-3 sm:grid-cols-2">{discovered.map((item) => { const added = drafts.some((draft) => draft.id === item.id); const maxTokens = discoveredCapacity(item.maxTokens); const contextWindow = discoveredCapacity(item.contextWindow); return <button key={item.id} type="button" className={`group flex items-center justify-between gap-3 rounded-xl border p-3 text-left transition ${added ? 'border-accent/80 bg-accent-tint/40 ring-2 ring-accent/10 ' : 'border-line/80 bg-canvas/60 hover:border-line-strong hover:bg-surface hover:shadow-sm'}`} onClick={() => add(item)}><span className="min-w-0"><span className={`block truncate font-mono text-xs font-semibold ${added ? 'text-accent-ink ' : 'text-ink '}`}>{item.id}</span><span className="mt-1 block truncate text-[11px] text-ink-3 ">{item.name ?? '上游未提供显示名称'}{maxTokens ? ` · 最大输出 ${maxTokens}` : ''}{contextWindow ? ` · 上下文 ${contextWindow}` : ''}</span></span><span className={`grid size-6 shrink-0 place-items-center rounded-lg ${added ? 'bg-accent text-white shadow-sm' : 'border border-line bg-surface text-ink-3 group-hover:text-ink-2 '}`}>{added ? <Check className="size-3.5" /> : <Plus className="size-3.5" />}</span></button>; })}</div> : null}{!current && discoverError ? <div className="mt-4 flex items-center gap-2 rounded-xl border border-red/75 bg-red-tint/90 px-3.5 py-3 text-xs text-red "><span className="grid size-6 shrink-0 place-items-center rounded-lg bg-red-tint/90 text-red "><AlertCircle className="size-3.5" /> </span><span><strong>模型发现失败：</strong>{discoverError}</span></div> : null}</section><div className="flex items-center justify-between"><div className="flex items-center gap-2.5"><span className="grid size-5 place-items-center rounded-md bg-ink text-[11px] font-bold text-canvas">{drafts.length}</span><div><p className="m-0 text-xs font-semibold text-ink ">{current ? '当前模型配置' : `已维护 ${drafts.length} 个模型`}</p><p className="mt-1 mb-0 text-[11px] text-ink-3 ">{current ? '配置卡片已展开；修改后保存即可。' : existingModels.length ? '已有模型直接保存更新，新加入的模型保存为新增。' : '可从列表移除选中的模型；配置卡片可展开细化。'}</p></div></div><div className="flex items-center gap-2">{drafts.length > 1 ? <button type="button" className="rounded bg-field px-2 py-0.5 text-[11px] text-ink-3 hover:bg-inset" onClick={() => setDrafts((items) => { const expanded = items.some((item) => item.expanded); return items.map((item) => ({ ...item, expanded: !expanded })); })}>{drafts.some((draft) => draft.expanded) ? '全部收起' : '全部展开'}</button> : null}{!current ? <Button type="button" size="sm" className="border border-accent bg-accent-tint/70 text-accent shadow-sm hover:bg-accent hover:text-white" onClick={() => setDrafts((items) => [...items, draftFrom(undefined, undefined, true)])}><Plus className="size-3.5" />新增模型</Button> : null}</div></div><div className="grid gap-4">{drafts.length ? drafts.map((draft, index) => <ModelConfigCard key={`${draft.id}-${index}`} index={index} draft={draft} onChange={(value) => setDrafts((items) => items.map((item, itemIndex) => itemIndex === index ? value : item))} onRemove={draft.existingModel ? undefined : () => setDrafts((items) => items.filter((_item, itemIndex) => itemIndex !== index))} />) : <div className="rounded-2xl border border-dashed border-line-strong px-4 py-12 text-center text-xs text-ink-3 "><Server className="mx-auto mb-2 size-7 text-ink-3 " />还没有选择模型，先获取可用模型或手动新增。</div>}</div>{error ? <p role="alert" className="m-0 flex items-center gap-2 rounded-xl bg-red-tint px-3 py-2 text-xs text-red "><AlertCircle className="size-3.5" />{error}</p> : null}</div><Footer onClose={onClose} saving={saving} disabled={!drafts.length || drafts.some((draft) => !draft.id.trim()) || invalidReasoning} label="保存" /></form></ProductDialog>;
}

export type ModelOnboardingPayload = ModelOnboardingWriteRequestWritable;
type ModelOnboardingProps = { providers: ReadonlyArray<Provider>; error?: string; onClose: () => void; onProbe: (value: ProviderProbeRequestWritable) => Promise<ProviderProbeResult>; onSave: (value: ModelOnboardingPayload) => void; saving: boolean };

export function ModelOnboardingDialog({ providers, error, onClose, onProbe, onSave, saving }: ModelOnboardingProps) {
 const [step, setStep] = React.useState(1);
 const [providerChoice, setProviderChoice] = React.useState(providers[0]?.id ?? 'custom');
 const [customName, setCustomName] = React.useState('');
 const [customDescription, setCustomDescription] = React.useState('');
 const [connectionName, setConnectionName] = React.useState('生产连接');
 const [apiProtocol, setApiProtocol] = React.useState<ModelProviderConnectionCreateRequestWritable['apiProtocol']>('openai-completions');
 const [baseUrl, setBaseUrl] = React.useState('');
 const [modelDiscoveryPath, setModelDiscoveryPath] = React.useState('/models');
 const [credential, setCredential] = React.useState('');
 const [discovered, setDiscovered] = React.useState<ProviderDiscoveredModel[]>([]);
 const [drafts, setDrafts] = React.useState<ModelDraft[]>([]);
 const [probing, setProbing] = React.useState(false);
 const [discoverError, setDiscoverError] = React.useState<string>();
 const [showKey, setShowKey] = React.useState(false);
 const custom = providerChoice === 'custom';
 const selectedProvider = providers.find((provider) => provider.id === providerChoice);
 const probeValue = { apiProtocol, baseUrl, modelDiscoveryPath, credential, connectTimeoutMs: 5000, readTimeoutMs: 120000 } satisfies ProviderProbeRequestWritable;
 const discover = async () => { setProbing(true); setDiscoverError(undefined); try { const result = await onProbe(probeValue); setDiscovered(result.models); if (!result.success) setDiscoverError(`${probeFailureMessage(result.upstreamStatus)}，仍可手动维护模型。`); } catch (cause) { setDiscoverError(cause instanceof Error ? cause.message : '模型发现失败；仍可手动维护模型。'); } finally { setProbing(false); } };
 const add = (model: ProviderDiscoveredModel) => setDrafts((items) => items.some((draft) => draft.id === model.id) ? items.filter((draft) => draft.id !== model.id) : [...items, draftFrom(undefined, model)]);
 const canNext = step === 1 ? Boolean(custom ? customName.trim() : providerChoice) : step === 2 ? Boolean(connectionName.trim() && baseUrl.trim() && credential.trim()) : step === 3 ? drafts.length > 0 && drafts.every((draft) => draft.id.trim() && (!draft.reasoningEnabled || !reasoningError(draft.reasoning))) : true;
 const save = () => onSave({ ...(custom ? { provider: { name: customName.trim(), description: customDescription.trim() } } : { providerId: providerChoice }), connection: { name: connectionName.trim(), apiProtocol, baseUrl: baseUrl.trim(), modelDiscoveryPath, credential, connectTimeoutMs: 5000, readTimeoutMs: 120000 }, models: drafts.map((draft) => { const value = modelPayload('pending', draft, 100); const { connectionId: _connectionId, ...onboardingModel } = value; return onboardingModel; }) });
 const titles = ['选择供应商', '配置连接', '获取可用模型', '确认保存'];
 const providerLabel = custom ? (customName || '新建自定义供应商') : selectedProvider?.name;
 return <ProductDialog className="flex min-h-0 max-w-[980px] flex-col overflow-hidden rounded-2xl border-line/90 " title="添加模型接入" onClose={onClose}><form className="grid min-h-0 flex-1 grid-rows-[auto_minmax(0,1fr)_auto] bg-canvas/40 " onSubmit={(event) => { event.preventDefault(); if (step === 4) save(); else if (canNext) setStep((value) => value + 1); }}><header className="border-b border-line bg-surface px-7 py-5"><div className="flex items-center justify-between"><div><h3 className="m-0 text-sm font-semibold text-ink ">{titles[step - 1]}</h3></div><span className="rounded-md bg-field px-2 py-0.5 font-mono text-xs font-semibold text-ink-3 ">{step} / 4</span></div><div className="mt-4 grid grid-cols-4 gap-3">{titles.map((title, index) => { const current = index + 1 === step; const passed = index + 1 < step; return <button type="button" key={title} disabled={index + 1 > step} onClick={() => setStep(index + 1)} className="group text-left disabled:cursor-not-allowed"><span className="mb-2 block h-1.5 overflow-hidden rounded-full bg-field "><span className={`block h-full rounded-full transition-all ${passed ? 'w-full bg-green ' : current ? 'w-full bg-ink ' : 'w-0'}`} /></span><span className={`flex items-center justify-between text-[11px] font-semibold ${passed ? 'text-green ' : current ? 'text-ink ' : 'text-ink-3 group-hover:text-ink-2 '}`}>{title}{passed ? <Check className="size-3" /> : null}</span></button>; })}</div></header><div className="min-h-0 overflow-y-auto px-7 py-6">{step === 1 ? <div className="grid gap-4"><div className="grid gap-3.5 sm:grid-cols-2">{providers.map((provider) => { const selected = !custom && providerChoice === provider.id; return <button type="button" key={provider.id} onClick={() => setProviderChoice(provider.id)} className={`group rounded-2xl border p-4 text-left transition ${selected ? 'border-ink-3 bg-ink/5 shadow-sm' : 'border-line/90 bg-surface hover:border-line-strong hover:bg-canvas/80 '}`}><div className="flex items-start justify-between gap-3"><span className="flex min-w-0 items-center gap-3.5"><span className={`grid size-10 shrink-0 place-items-center rounded-xl bg-gradient-to-br ${providerGradient(provider.id, provider.name)} text-sm font-bold text-white shadow-sm`}>{provider.name.slice(0, 1).toUpperCase()}</span><span className="min-w-0"><strong className="block truncate text-sm text-ink ">{provider.name}</strong><small className="mt-0.5 flex items-center gap-1.5 text-xs text-ink-3 "><span className={`size-1.5 rounded-full 'bg-green '`} />已有供应商 · {provider.connectionCount ?? 0} 个连接</small></span></span><span className={`grid size-5 place-items-center rounded-full border ${selected ? 'border-ink bg-ink text-canvas shadow-sm' : 'border-line-strong bg-surface '}`}>{selected ? <Check className="size-3" /> : null}</span></div><p className={`mt-3 border-t pt-2.5 text-[11px] leading-relaxed ${selected ? 'border-ink/30 text-ink-2 ' : 'border-line text-ink-3 '}`}>选择此供应商后创建新的连接。</p></button>; })}<button type="button" onClick={() => setProviderChoice('custom')} className={`group rounded-2xl border p-4 text-left transition ${custom ? 'border-ink-3 bg-ink/5 shadow-sm' : 'border-line/90 bg-field/70 hover:border-line-strong '}`}><div className="flex items-start justify-between gap-3"><span className="flex items-center gap-3.5"><span className={`grid size-10 place-items-center rounded-xl border ${custom ? 'border-ink bg-ink text-canvas' : 'border-line bg-surface text-ink-2 '}`}><Plus className="size-4" /></span><span><strong className="block text-sm text-ink ">+ 新建供应商</strong><small className="mt-0.5 block text-xs text-ink-3 ">自定义供应商接入</small></span></span><span className={`grid size-5 place-items-center rounded-full border ${custom ? 'border-ink bg-ink text-canvas' : 'border-line-strong bg-surface '}`}>{custom ? <Check className="size-3" /> : null}</span></div><p className={`mt-3 border-t pt-2.5 text-[11px] leading-relaxed ${custom ? 'border-ink/30 text-ink-2 ' : 'border-line/60 text-ink-3 '}`}>先保存供应商元信息，再创建新的连接。</p></button></div>{custom ? <div className={`${panelClass} grid gap-4 p-5`}><div className="flex items-center justify-between"><span className="text-xs font-semibold text-ink ">新建供应商元信息</span><span className="text-[11px] text-ink-3 ">保存后自动进入下一步配置连接</span></div><div className="grid gap-4 sm:grid-cols-2"><TextField label="供应商名称" value={customName} onChange={setCustomName} placeholder="例如：Atria / vLLM 自建集群" /><TextField label="供应商描述（选填）" value={customDescription} onChange={setCustomDescription} placeholder="例如：团队统一的 OpenAI 兼容网关" /></div></div> : null}</div> : null}{step === 2 ? <div className="grid gap-4"><div className={`${panelClass} flex items-center gap-3 p-3.5`}><div className={`grid size-9 shrink-0 place-items-center rounded-xl bg-gradient-to-br ${custom ? 'from-zinc-700 dark:from-ink to-zinc-900 dark:to-ink' : providerGradient(custom ? undefined : selectedProvider?.id, providerLabel ?? '')} text-sm font-bold text-white`}>{(providerLabel ?? '新').slice(0, 1)}</div><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><strong className="truncate text-xs text-ink sm:text-sm">{providerLabel}</strong><span className="rounded-full border border-line/70 bg-field px-2 py-0.5 text-[10px] font-medium text-ink-2 ">{custom ? '首次创建连接' : '已有供应商'}</span></div><p className="mt-0.5 mb-0 truncate text-[11px] text-ink-3 ">端点与 API Key 只保存到这条连接</p></div><button type="button" className="ml-auto rounded-full border border-line/80 bg-canvas px-2.5 py-1.5 text-[11px] font-medium text-ink-3 hover:bg-field " onClick={() => setStep(1)}>切换供应商</button></div><section className={`${panelClass} grid gap-5 overflow-hidden`}><div className="grid gap-4 p-5 sm:grid-cols-2"><TextField label="连接名称" value={connectionName} onChange={setConnectionName} placeholder="例如：生产连接" /><label className="grid gap-1.5 text-[11px] font-semibold text-ink-2 ">API 协议<select className={inputClass} value={apiProtocol} onChange={(event) => setApiProtocol(event.target.value as typeof apiProtocol)}><option value="openai-completions">OpenAI Chat Completions</option><option value="openai-responses">OpenAI Responses API</option><option value="anthropic-messages">Anthropic Messages API</option></select></label></div><div className="grid gap-4 border-t border-line p-5"><TextField label="Base URL" value={baseUrl} onChange={setBaseUrl} placeholder="https://api.example.com/v1" icon={Globe} /><TextField label="模型发现接口" value={modelDiscoveryPath} onChange={setModelDiscoveryPath} placeholder="/models" /><div className="grid gap-1.5"><div className="flex items-center justify-between"><label className="text-[11px] font-semibold text-ink-2 ">API Key</label><span className="inline-flex items-center gap-1 text-[10px] font-medium text-green "><Lock className="size-3" />凭据只在连接步骤配置</span></div><div className="relative"><KeyRound className="pointer-events-none absolute left-3 top-1/2 size-3.5 -translate-y-1/2 text-ink-3 " /><input aria-label="API Key" className={`${inputClass} pl-9 pr-20 font-mono`} type={showKey ? 'text' : 'password'} value={credential} onChange={(event) => setCredential(event.target.value)} placeholder="输入连接密钥 (例如 sk-...)" /><button type="button" className="absolute right-2 top-1/2 inline-flex -translate-y-1/2 items-center gap-1 rounded-full px-2 py-1 text-[10px] text-ink-3 hover:bg-field " onClick={() => setShowKey((value) => !value)}>{showKey ? <EyeOff className="size-3.5" /> : <Eye className="size-3.5" />}{showKey ? '隐藏' : '显示'}</button></div></div><div className="flex items-center gap-2 rounded-xl border border-accent-tint bg-accent-tint/50 px-3 py-2 text-[11px] text-accent-ink "><ShieldCheck className="size-3.5 shrink-0 text-accent " />下一步“获取可用模型”会直接验证端点和 API Key，无需在这里重复测试。</div></div></section></div> : null}{step === 3 ? <div className="grid gap-5"><section className={`${panelClass} relative overflow-hidden p-5`}><div className="absolute -right-14 -top-14 size-36 rounded-full bg-gradient-to-bl from-blue-500/10 via-indigo-500/5 to-transparent" /><div className="relative flex items-start justify-between gap-4"><div className="flex items-start gap-3"><div className={`grid size-10 shrink-0 place-items-center rounded-xl border ${probing ? 'border-accent bg-accent-tint text-accent ' : discovered.length ? 'border-green bg-green-tint text-green ' : 'border-line/80 bg-canvas text-ink-2 '}`}>{probing ? <RefreshCw className="size-4 animate-spin" /> : discovered.length ? <Sparkles className="size-4" /> : <Server className="size-4" />}</div><div><div className="flex flex-wrap items-center gap-2"><h3 className="m-0 text-sm font-semibold text-ink ">可用模型</h3><span className="inline-flex items-center gap-1 rounded-full border border-line/60 bg-field/90 px-2 py-0.5 text-[10px] font-medium text-ink-3 "><span className="size-1.5 rounded-full bg-green " />{connectionName}</span>{discovered.length ? <span className="rounded-full border border-green/60 bg-green-tint px-2 py-0.5 text-[10px] font-semibold text-green ">已同步 {discovered.length} 款候选</span> : null}</div><p className="mt-1 mb-0 text-[11px] leading-relaxed text-ink-3 ">点击选择，已选择模型会进入下方配置列表。发现失败时仍可在下方手动维护。</p></div></div><Button type="button" size="sm" className="border border-line/90 bg-surface text-ink shadow-sm hover:bg-ink hover:text-canvas" disabled={probing} onClick={() => void discover()}><RefreshCw className={`size-3.5 ${probing ? 'animate-spin' : ''}`} />{probing ? '正在探测上游目录…' : discovered.length ? '重新获取' : '获取可用模型'}</Button></div>{discovered.length ? <div className="relative mt-4 grid gap-2.5 border-t border-line pt-3.5 sm:grid-cols-2">{discovered.map((item) => { const added = drafts.some((draft) => draft.id === item.id); const contextWindow = discoveredCapacity(item.contextWindow); const maxTokens = discoveredCapacity(item.maxTokens); return <button key={item.id} type="button" onClick={() => add(item)} className={`group flex items-center justify-between gap-3 rounded-xl border p-3 text-left transition ${added ? 'border-accent/80 bg-accent-tint/40 ring-2 ring-accent/10 shadow-sm' : 'border-line/80 bg-canvas/60 hover:border-line-strong hover:bg-surface hover:shadow-sm'}`}><span className="min-w-0"><span className={`flex items-center gap-1.5 truncate font-mono text-xs font-semibold ${added ? 'text-accent-ink ' : 'text-ink '}`}>{item.id}{contextWindow ? <span className="rounded bg-surface px-1.5 py-0.5 text-[10px] text-ink-3 ">{contextWindow}</span> : null}</span><span className="mt-1 block truncate text-[11px] text-ink-3 ">显示名称：{item.name ?? item.id}{maxTokens ? ` · 最大输出 ${maxTokens}` : ''}</span></span><span className={`grid size-6 place-items-center rounded-lg ${added ? 'bg-accent text-white shadow-sm' : 'border border-line bg-surface text-ink-3 group-hover:text-ink-2 '}`}>{added ? <Check className="size-3.5" /> : <Plus className="size-3.5" />}</span></button>; })}</div> : null}{discoverError ? <div className="mt-4 flex items-center gap-2 rounded-xl border border-red/75 bg-gradient-to-r from-rose-50/90 via-rose-50/50 to-amber-50/30 px-3.5 py-3 text-xs text-red "><span className="grid size-6 shrink-0 place-items-center rounded-lg bg-red-tint/90 text-red "><AlertCircle className="size-3.5" /></span><span><strong>模型发现失败：</strong>{discoverError}</span></div> : null}</section><div className="flex items-center justify-between"><div className="flex items-center gap-2.5"><span className="grid size-5 place-items-center rounded-md bg-ink text-[11px] font-bold text-canvas">{drafts.length}</span><span className="text-xs font-semibold text-ink ">已选择 {drafts.length} 个模型</span></div><Button type="button" size="sm" className="border border-accent bg-accent-tint/70 text-accent shadow-sm hover:bg-accent hover:text-white" onClick={() => setDrafts((items) => [...items, draftFrom(undefined, undefined, true)])}><Plus className="size-3.5" />手动维护模型</Button></div><div className="grid gap-4">{drafts.map((draft, index) => <ModelConfigCard key={`${draft.id}-${index}`} index={index} draft={draft} onChange={(value) => setDrafts((items) => items.map((item, itemIndex) => itemIndex === index ? value : item))} onRemove={() => setDrafts((items) => items.filter((_item, itemIndex) => itemIndex !== index))} />)}</div></div> : null}{step === 4 ? <div className="grid gap-4"><section className={`${panelClass} p-5`}><div className="mb-3 flex items-center gap-1.5 text-xs font-semibold text-ink "><CheckCircle2 className="size-4 text-green " />即将上线连接与受管模型概览</div><div className="grid gap-4 rounded-xl border border-line/60 bg-canvas p-3.5 sm:grid-cols-4"><div><span className="block text-[11px] text-ink-3 ">所属供应商</span><strong className="mt-0.5 block text-sm text-ink ">{providerLabel}</strong></div><div><span className="block text-[11px] text-ink-3 ">连接通道名称</span><strong className="mt-0.5 block text-sm text-ink ">{connectionName}</strong></div><div><span className="block text-[11px] text-ink-3 ">API 协议规范</span><strong className="mt-0.5 block truncate text-xs text-ink ">{apiProtocol}</strong></div><div><span className="block text-[11px] text-ink-3 ">本次纳管模型数</span><strong className="mt-0.5 block text-sm text-green ">{drafts.length} 款模型</strong></div></div></section><section className={`${panelClass} overflow-hidden`}><div className="flex items-center justify-between border-b border-line bg-canvas/80 px-4 py-3 text-xs font-semibold text-ink-2 "><span>模型配置清单</span><span className="text-[11px] font-normal text-ink-3 ">上线后默认状态为「已启用」</span></div><div className="divide-y divide-line ">{drafts.map((draft, index) => <div key={`${draft.id}-${index}`} className="flex flex-col justify-between gap-3 p-4 sm:flex-row sm:items-center"><div className="space-y-1"><div className="flex items-center gap-2"><span className="grid size-4 place-items-center rounded bg-field text-[10px] font-bold text-ink-2 ">{index + 1}</span><span className="text-xs font-semibold text-ink ">{draft.name || draft.id || '未命名手动模型'}</span><span className="rounded border border-line/60 bg-canvas px-1.5 py-0.5 font-mono text-[11px] text-ink-3 ">{draft.id || '待填写'}</span></div><div className="flex items-center gap-2 pl-6">{draft.input.includes('text') ? <span className="rounded bg-field px-1.5 py-0.5 text-[10px] text-ink-2 ">文本</span> : null}{draft.input.includes('image') ? <span className="rounded bg-accent-tint px-1.5 py-0.5 text-[10px] text-accent-ink ">图片</span> : null}{draft.reasoningEnabled ? <span className="rounded border border-orange/60 bg-orange-tint px-1.5 py-0.5 text-[10px] text-orange ">推理档位：{draft.reasoning.length} 档</span> : null}</div></div><div className="flex items-center gap-4 pl-6 font-mono text-[11px] text-ink-3 sm:pl-0">上下文：<strong className="text-ink ">{draft.contextWindow}</strong> · 最大输出：<strong className="text-ink ">{draft.maxTokens}</strong></div></div>)}</div></section><div className="flex items-center gap-2 rounded-xl bg-green-tint px-3 py-2 text-xs text-green "><CheckCircle2 className="size-3.5" />保存模型不会自动授权成员，完成后可在模型集或访问策略中继续配置。</div></div> : null}</div><DialogFooter className="bg-canvas/95 px-7"><Button type="button" size="sm" disabled={saving} onClick={() => step > 1 ? setStep((value) => value - 1) : onClose()}>{step > 1 ? '返回' : '取消'}</Button><Button type="submit" variant="primary" size="sm" disabled={saving || !canNext}>{saving ? '保存中' : step === 4 ? '确认并保存接入' : '继续'}{step === 4 ? <Check className="size-3.5" /> : <ChevronRight className="size-3.5" />}</Button></DialogFooter></form></ProductDialog>;
}

export function DeleteModelDialog({ error, label, onClose, onConfirm, saving }: { error?: string; label: string; onClose: () => void; onConfirm: () => void; saving: boolean }) {
 return <ProductDialog className="max-w-[520px] overflow-y-auto rounded-2xl border-line/90 " title="确认删除" onClose={onClose}><div className="grid gap-5 bg-canvas/50 p-5"><div className="flex items-start gap-3 rounded-xl border border-red/70 bg-red-tint/70 p-4"><Trash2 className="mt-0.5 size-4 shrink-0 text-red " /><p className="m-0 text-xs leading-6 text-red ">确认删除模型“{label}”？已被授权或记录使用的模型需要先停用。</p></div>{error ? <p role="alert" className="m-0 flex items-center gap-2 rounded-xl bg-red-tint px-3 py-2 text-xs text-red "><AlertCircle className="size-3.5" />{error}</p> : null}<DialogFooter sticky><Button type="button" size="sm" disabled={saving} onClick={onClose}>取消</Button><Button type="button" variant="primary" size="sm" className="bg-red text-white hover:brightness-95" disabled={saving} onClick={onConfirm}>{saving ? '删除中' : '删除'}<Trash2 className="size-3.5" /></Button></DialogFooter></div></ProductDialog>;
}
